const UR_RULES = [
  [/^(\d+) items?$/, "$1 آئٹمز"], [/^Page (\d+) of (\d+)$/, "صفحہ $1 از $2"], [/^View all (.+) →$/, (m, x) => "تمام " + urCat(x) + " دیکھیں ←"], [/^(\d+) products?$/, "$1 پروڈکٹس"], [/^Products \((\d+)\)$/, "پروڈکٹس ($1)"],
  [/^Sizes: (.*)$/, "سائز: $1"], [/^ONLY (\d+) LEFT$/, "صرف $1 باقی"], [/^(\d+) designs$/, "$1 ڈیزائن"], [/^(\d+) photos$/, "$1 تصاویر"],
  [/^Code: (.*)$/, "کوڈ: $1"], [/^Delivery \((\d+) products × (\d+)\)$/, "ڈیلیوری ($1 پروڈکٹس × $2)"], [/^(\d+)% OFF$/, "$1% رعایت"],
  [/^Delivery in 3-5 days \| Charges (.+)$/, "3 سے 5 دن میں ڈیلیوری | چارجز $1"], [/^(\d+) in stock$/, "$1 اسٹاک میں"],
  [/^Delivery all over Pakistan\. Delivery is (.+) per product \(may vary slightly by city\/area\)\.$/, "پورے پاکستان میں ڈیلیوری۔ ہر پروڈکٹ پر $1 (شہر/علاقے کے حساب سے تھوڑا فرق ہو سکتا ہے)۔"],
  [/^Buy (\d+)\+ items worth (.+) or more and delivery is FREE\.$/, "$1 یا زیادہ آئٹمز $2 یا زیادہ کے خریدیں تو ڈیلیوری فری۔"],
  [/^Buy (.+) Online$/, (m, x) => urCat(x) + " آن لائن خریدیں"], [/^SHOP (.+)$/, (m, x) => urCat(x)],
  [/^Shop (.+) by budget$/, (m, x) => "بجٹ کے مطابق " + urCat(x)], [/^Under Rs\. ([\d,]+)$/, "$1 روپے سے کم"],
  [/^(.+) \((\d+)\)$/, (m, x, n) => UR[x] ? UR[x] + " (" + n + ")" : m],
  [/^🚚 Add (.+) to get$/, (m, x) => "🚚 " + x.replace(/Rs\. ([\d,]+) more/, "مزید $1 روپے").replace(/(\d+) more items?/, "$1 مزید آئٹم").replace(" and ", " اور ") + " ڈالیں تو ملے گی"]
];
const UR_UP = {}; Object.keys(UR).forEach(k => UR_UP[k.toUpperCase()] = UR[k]);
const urCat = x => UR[x] || UR_UP[x] || x;
function trUR(str){
  const k = String(str).replace(/\s+/g, " ").trim(); if (!k) return null;
  let v = UR[k];
  if (v === undefined) for (const [re, rp] of UR_RULES){ if (re.test(k)){ v = k.replace(re, rp); break; } }
  if (v === undefined) return null;
  const lead = str.match(/^\s*/)[0], trail = str.match(/\s*$/)[0];
  return lead + v + trail;
}
const T = s => LANG === "ur" ? (trUR(s) ?? s) : s;
const TR_ATTRS = ["placeholder", "aria-label", "title"];
function trEl(el){ TR_ATTRS.forEach(a => { if (el.hasAttribute(a)){ const v = trUR(el.getAttribute(a)); if (v !== null && v !== el.getAttribute(a)) el.setAttribute(a, v); } }); }
function translateNode(root){
  if (LANG !== "ur" || !root) return;
  if (root.nodeType === 3){ const p = root.parentElement; if (p && p.closest("script,style,.no-tr")) return; const v = trUR(root.nodeValue); if (v !== null && v !== root.nodeValue) root.nodeValue = v; return; }
  if (root.nodeType !== 1 || root.closest("script,style,.no-tr")) return;
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT); let n; const nodes = [];
  while ((n = w.nextNode())){ const p = n.parentElement; if (p && !p.closest("script,style,.no-tr")) nodes.push(n); }
  nodes.forEach(t => { const v = trUR(t.nodeValue); if (v !== null && v !== t.nodeValue) t.nodeValue = v; });
  trEl(root); root.querySelectorAll("[placeholder],[aria-label],[title]").forEach(trEl);
}
function applyLang(){
  const ur = LANG === "ur";
  document.documentElement.lang = ur ? "ur" : "en-PK";
  document.documentElement.dir = ur ? "rtl" : "ltr";
  const lbl = document.getElementById("langLbl"); if (lbl) lbl.innerHTML = ur ? '<span class="lg">English</span><span class="sm">EN</span>' : "اردو";
  if (!ur) return;
  if (!document.getElementById("urFont")){
    const l = document.createElement("link"); l.id = "urFont"; l.rel = "stylesheet";
    l.href = "https://fonts.googleapis.com/css2?family=Noto+Naskh+Arabic:wght@400;500;600;700&display=swap"; document.head.appendChild(l);
  }
  translateNode(document.body);
  new MutationObserver(list => list.forEach(m => {
    if (m.type === "characterData") translateNode(m.target);
    else m.addedNodes.forEach(nd => translateNode(nd));
  })).observe(document.body, {childList: true, subtree: true, characterData: true});
}
function toggleLang(){
  try { localStorage.setItem("ud_lang", LANG === "ur" ? "en" : "ur"); } catch (e) {}
  location.reload();
}
