const imgUrl = (s, original) => { s = String(s || "").trim(); if (!s) return "images/logo.png"; const id = driveId(s); if (id && DVMAP[id]) s = DVMAP[id]; else if (id) return "https://lh3.googleusercontent.com/d/" + id + (original ? "" : "=w1000"); s = /^https?:\/\//i.test(s) ? s : "images/" + s;
  /* product photos in img/ also have a lighter .webp copy (same name); the page falls back to .jpg if it is missing */
  return (!original && /(^|\/)img\/[a-z]+\/[a-z]+-\d+\.jpg$/i.test(s)) ? s.replace(/\.jpg$/i, ".webp") : s; };
/* if a Drive image fails on lh3, try Drive's thumbnail link once, then the logo */
document.addEventListener("error", e => {
  const im = e.target; if (!im || im.tagName !== "IMG") return;
  if (im.dataset.k !== undefined){ const sp = document.createElement("span"); sp.className = "fbico"; sp.innerHTML = icon(im.dataset.k); im.replaceWith(sp); return; }
  /* product photos live in img/<prefix>/ (e.g. img/ug/ug-020.jpg); older ones may still be in the root: try the other place once */
  { const sw = im.getAttribute("src") || ""; if (!im.dataset.wb && /\/?img\/[a-z]+\/[^\/?#]+\.webp$/i.test(sw)){ im.dataset.wb = 1; im.src = sw.replace(/\.webp$/i, ".jpg"); return; } }
  if (!im.dataset.mv){ const s0 = im.getAttribute("src") || ""; let p = s0.match(/^(.*?\/|)img\/[a-z]+\/([a-z]+-\d+[^\/?#]*)$/);
    if (p){ im.dataset.mv = 1; im.src = p[1] + p[2]; return; }
    p = s0.match(/^(https:\/\/umar-deals\.pages\.dev\/|\.\/|)(([a-z]+)-\d+[^\/?#]*\.(?:jpe?g|png|webp))$/i);
    if (p){ im.dataset.mv = 1; im.src = p[1] + "img/" + p[3].toLowerCase() + "/" + p[2]; return; } }
  const m = (im.getAttribute("src") || "").match(/lh3\.googleusercontent\.com\/d\/([-\w]+)/);
  if (m && !im.dataset.fb){ im.dataset.fb = 1; im.src = "https://drive.google.com/thumbnail?id=" + m[1] + "&sz=w1000"; }
  else if (im.dataset.fb !== "2" && !/logo\.png$/.test(im.src)){ im.dataset.fb = "2"; im.src = "images/logo.png"; }
}, true);
