function parseCSV(text){
  const rows = []; let row = [], cell = "", q = false;
  text = text.replace(/^﻿/, "");
  for (let i = 0; i < text.length; i++){
    const c = text[i];
    if (q){
      if (c === '"' && text[i+1] === '"'){ cell += '"'; i++; }
      else if (c === '"') q = false;
      else cell += c;
    } else if (c === '"') q = true;
    else if (c === ",") { row.push(cell); cell = ""; }
    else if (c === "\n" || c === "\r"){
      if (c === "\r" && text[i+1] === "\n") i++;
      row.push(cell); rows.push(row); row = []; cell = "";
    } else cell += c;
  }
  if (cell !== "" || row.length) { row.push(cell); rows.push(row); }
  const head = (rows.shift() || []).map(h => h.trim().toLowerCase());
  return rows.filter(r => r.some(x => x.trim() !== "")).map(r => Object.fromEntries(head.map((h, i) => [h, (r[i] || "").trim()])));
}

/* fetch a CSV: Google Sheet first, local backup file if the sheet can't be reached */
async function getCSV(url, backup){
  for (const u of [url, backup].filter(Boolean)){
    try { const r = await fetch(u, {cache: "no-store"}); if (!r.ok) continue; const t = await r.text(); if (t.trim() && !/^\s*</.test(t)) return t; } catch (e) {}
  }
  throw new Error("csv");
}
/* fast first paint: show the last saved copy (or the site's own CSV file) at once,
   then check the Google Sheet in the background and refresh the page data if the sheet changed */
const CSV_LIVE = []; let CSV_REFRESH = false;
const csvOk = x => x && x.trim() && !/^\s*</.test(x) ? x : null;
async function getCSVQuick(url, backup){
  const key = "ud_csv_" + backup; let t = null;
  try { t = localStorage.getItem(key); } catch (e) {}
  if (CSV_REFRESH && t) return t;
  const live = url ? fetch(url, {cache: "no-store"}).then(r => r.ok ? r.text() : null).then(csvOk).catch(() => null) : Promise.resolve(null);
  if (!t){ try { const r = await fetch(backup, {cache: "no-cache"}); if (r.ok) t = csvOk(await r.text()); } catch (e) {} }
  if (!t){ t = await live; if (!t) throw new Error("csv"); try { localStorage.setItem(key, t); } catch (e) {} return t; }
  CSV_LIVE.push(live.then(x => { if (!x) return false; try { localStorage.setItem(key, x); } catch (e) {} return x !== t; }));
  return t;
}

