let REVIEWS = [];
const stars = n => { n = Math.max(1, Math.min(5, Math.round(+n || 5))); return "★".repeat(n) + "☆".repeat(5 - n); };
function revCard(r, withProduct){
  const p = withProduct && r.code ? PRODUCTS.find(x => x.code === r.code) : null;
  return `<div class="rev"><div class="st" aria-label="${esc(r.rating || 5)} out of 5">${stars(r.rating)}</div>${r.photo ? `<img src="${esc(imgUrl(r.photo))}" alt="Customer photo" loading="lazy">` : ""}<p>${esc(r.text)}</p><small>${esc(r.name || "Customer")}${r.city ? ", " + esc(r.city) : ""}${r.date ? " • " + esc(r.date) : ""}</small>${p ? `<a class="rp" href="#" onclick="openProduct('${jsq(p.code)}');return false">${esc(p.name)}</a>` : ""}</div>`;
}
function renderReviews(){
  const box = $("#revs"); if (!box) return;
  box.innerHTML = REVIEWS.slice(0, 12).map(r => revCard(r, true)).join("");
  const b = $("#revBtn"); if (b) b.href = waLink("Assalam o Alaikum! Mujhe order mil gaya. Mera review: \n\nRating (1-5): \nProduct code: \nMera naam aur shehar: \n\nAap ye review website pe laga sakte hain: Haan / Nahi");
}
async function loadReviews(){
  try { REVIEWS = parseCSV(await getCSV("", "reviews.csv")).filter(r => (r.text || "").trim()); } catch (e) { REVIEWS = []; }
  REVIEWS.reverse(); renderReviews();
}
