/* Description: drop the product name when the text just repeats it */
function cleanDesc(d, name){
  d = String(d || "").trim();
  if (name && d.toLowerCase().startsWith(name.toLowerCase() + ".")) d = d.slice(name.length + 1).trim();
  return d;
}
const UNSTITCHED_RE = /unstitched|\bfabric\b/i;
function yearSteps(a, b){
  const out = [], step = (b - a) > 6 ? 2 : 1;
  for (let y = a; y < b; y += step) out.push(`${y}-${Math.min(y + step, b)} Years`);
  return out.length ? out : [`${a}-${b} Years`];
}
/* Sizes to offer when the sheet's "sizes" column is empty. Only for things you wear. */
function autoSizes(p){
  const n = " " + (p.en || p.name || "").toLowerCase() + " ", cats = p.cats, subs = p.subs;
  const has = c => cats.includes(c), sub = s => subs.includes(s);
  const wearCats = ["Women Stitched","Men Stitched","Kids Clothing","Women Undergarments","Men Undergarments","Shoes"];
  const wearWinter = ["Hoodies & Sweatshirts","Jackets & Cardigans","Fleece Trousers","Women Winter Wear","Kids Winter Wear","Socks & Thermals"];
  const isWear = cats.some(c => wearCats.includes(c)) || (has("Winter") && subs.some(s => wearWinter.includes(s))) || (has("Fitness") && sub("Sports Wear"));
  if (!isWear || UNSTITCHED_RE.test(n) || sub("Women Care") || cats.some(c => /Unstitched|Shawls/.test(c))) return [];
  if (/free size|one size/.test(n)) return ["Free Size"];
  if (has("Winter") && !cats.some(c => wearCats.includes(c)) && /sock|cap|glove|muffler|beanie/.test(n)) return [];
  /* kids */
  const kid = has("Kids Clothing") || sub("Kids Winter Wear") || sub("Kids Shoes");
  if (kid && !has("Shoes")){
    let m = n.match(/(\d{1,2})\s*-\s*(\d{1,2})\s*months?/); if (m) return [`${m[1]}-${m[2]} Months`];
    m = n.match(/(\d{1,2})\s*-\s*(\d{1,2})\s*(?:y|yr|yrs|year|years)\b/); if (m && +m[2] > +m[1]) return yearSteps(+m[1], +m[2]);
    m = n.match(/\b(\d{2,3})\s*cm\b/); if (m) return [`${m[1]} cm`];
    return ["1-2 Years","3-4 Years","5-6 Years","7-8 Years","9-10 Years"];
  }
  /* shoes */
  if (has("Shoes")){
    if (sub("Kids Shoes") || /\b(kids?|boys?|baby|child)\b/.test(n)) return ["26","28","30","32","34"];
    if (subs.some(s => /^Women|Heels/.test(s)) || /\b(women|ladies|girls?|female)\b/.test(n)) return ["36","37","38","39","40","41"];
    if (/\bmen\b|\bmen's\b|\bboys\b|\bgents\b/.test(n) || sub("Men Shoes")) return ["39","40","41","42","43","44"];
    return ["37","38","39","40","41","42","43","44"];
  }
  /* bras: band sizes */
  if (sub("Bras")){
    const m = n.match(/\b(2[8-9]|3\d|4[0-8])\s*-\s*(3\d|4[0-8])\b/);
    if (m){ const out = []; for (let s = +m[1]; s <= +m[2]; s += 2) out.push(String(s)); return out; }
    return ["32","34","36","38","40"];
  }
  /* sizes written in the name */
  const L = ["S","M","L","XL","XXL","3XL"];
  const span = (a, b) => L.slice(L.indexOf(a), L.indexOf(b) + 1);
  if (/\bs\s*-\s*3xl\b/.test(n)) return span("S","3XL");
  if (/\bs\s*-\s*(xxl|2xl)\b/.test(n)) return span("S","XXL");
  if (/small to xl/.test(n)) return span("S","XL");
  if (/medium to xl/.test(n)) return span("M","XL");
  if (/\bm l xl\b/.test(n)) return span("M","XL");
  if (/\bs m l\b/.test(n)) return span("S","L");
  if (/\bm l\b/.test(n)) return ["M","L"];
  let m = n.match(/\b(xxl|xl)\b/); if (m && !/plus size/.test(n)) return [m[1].toUpperCase()];
  if (/\blarge\s*$/.test(n.trim())) return ["L"];
  if (/\bmedium\s*$/.test(n.trim())) return ["M"];
  /* defaults by category */
  if (sub("Panties")) return ["M","L","XL"];
  if (sub("Thermals") || sub("Socks & Thermals")) return ["M","L","XL"];
  if (has("Women Undergarments") || has("Women Stitched") || sub("Women Winter Wear")) return ["S","M","L","XL"];
  return ["M","L","XL","XXL"];   /* men's wear */
}
const FABRICS = ["lawn","chiffon","organza","khaddar","karandi","dhanak","marina","linen","cotton","katan silk","ice silk","shamoz silk","silk","velvet","wool","fleece","jersey","net","crepe","malai","bareeza","leather","denim","corduroy","satin","lycra","spandex","polyester","nylon","cashmere","pashmina","terry","dobby","chikankari","jacquard","acrylic","stainless steel","abs"];
const COLOURS = ["off-white","sky blue","navy blue","black","white","red","maroon","pink","peach","purple","lavender","blue","navy","green","olive","teal","turquoise","yellow","mustard","orange","brown","beige","khaki","grey","gray","cream","fuchsia","multicolor","multicolour"];
const cap = s => s.replace(/\b\w/g, c => c.toUpperCase());
function findAll(n, words){
  const out = []; let t = " " + n + " ";
  words.forEach(w => { const re = new RegExp("[^a-z]" + w.replace(/[-\s]/g, "[-\\s]") + "[^a-z]"); if (re.test(t)){ out.push(w); t = t.replace(re, " "); } });
  return out;
}
/* Short "facts" list for the product page, built only from what the name and category say */
function autoFacts(p){
  const n = (p.en || p.name || "").toLowerCase(), f = [];
  const wear = p.sizes.length || p.cats.some(c => /Stitched|Unstitched|Shawls|Undergarments|Clothing/.test(c));
  const fab = findAll(n, FABRICS).filter(x => wear || ["stainless steel","abs","leather","silicone"].includes(x));
  if (fab.length) f.push(["Material", fab.map(x => x === "abs" ? "ABS plastic" : cap(x)).join(", ")]);
  let m = n.match(/(\d)\s*-?\s*(?:pcs?|pieces?)\b/);
  if (m && p.cats.some(c => /Stitched|Unstitched/.test(c))){
    const k = +m[1];
    f.push(["Pieces", k === 3 ? "3 pieces: shirt, trouser and dupatta" : k === 2 ? (/dupatta/.test(n) ? "2 pieces: shirt and dupatta" : "2 pieces: shirt and trouser") : k === 1 ? "1 piece: shirt only" : `${k} pieces`]);
  } else if ((m = n.match(/pack of (\d+)|(\d+)\s*-?\s*pack\b|(\d+)\s*pairs?\b/))){
    f.push(["In the pack", (m[1] || m[2] || m[3]) + " pieces"]);
  }
  const col = findAll(n, COLOURS).map(c => c === "gray" ? "grey" : c);
  if (col.length) f.push(["Colour", [...new Set(col)].map(cap).join(" / ") + " (as shown in the photo)"]);
  if (p.sizes.length) f.push(["Sizes", p.sizes.join(", ")]);
  const fs = fab.join(" ");
  if (p.cats.some(c => /Undergarments/.test(c))) f.push(["Care", "Hand wash in cold water. Do not bleach. Packed discreetly."]);
  else if (/wool|fleece|cashmere|pashmina|velvet/.test(fs) || p.cats.some(c => /Shawls/.test(c))) f.push(["Care", "Hand wash in cold water or dry clean. Dry flat in the shade."]);
  else if (/chiffon|organza|net|silk|crepe|satin|bareeza/.test(fs)) f.push(["Care", "Dry clean or gentle hand wash in cold water. Iron on low heat."]);
  else if (wear && /lawn|cotton|linen|khaddar|karandi|dhanak|marina|jersey|terry|dobby|polyester|lycra|denim/.test(fs)) f.push(["Care", "Hand wash or gentle machine wash in cold water. Iron on medium heat."]);
  if (!wear){
    const spec = (n.match(/\b\d+(?:\.\d+)?\s?(?:mah|kg|g|ml|l|w|v|inch|cm|mm|digit|pcs?|piece|liter|litre)\b/g) || []).slice(0, 4);
    const feat = ["rechargeable","portable","foldable","waterproof","wireless","bluetooth","lcd","led","usb","adjustable","fast charging","stainless steel","non-stick","automatic","digital"].filter(w => n.includes(w));
    const all = [...new Set([...spec.map(s => s.replace(/\s+/g, " ")), ...feat])];
    if (all.length) f.push(["Features", all.map(x => /^[a-z]/.test(x) && x.length <= 3 ? x.toUpperCase() : cap(x)).join(" · ")]);
  }
  const subs = p.subs.join(" ");
  if (/Wedding|Eid|Party/.test(subs)) f.push(["Good for", "Eid, weddings and parties"]);
  else if (/Night/.test(subs)) f.push(["Good for", "Sleeping and relaxing at home"]);
  else if (/Sports Wear|Gym/.test(subs)) f.push(["Good for", "Gym, walking and sports"]);
  else if (p.cats.includes("Winter")) f.push(["Good for", "Cold weather"]);
  return f;
}
/* colour variants: products with the same "group" (sheet column) show as one card, with a colour picker inside */
let VARS = {};
const varsOf = p => (p && p.group && VARS[p.group]) || null;
function collapseGroups(arr){ const seen = new Set(); return arr.filter(p => { const g = varsOf(p) && p.group; if (!g) return true; if (seen.has(g)) return false; seen.add(g); return true; }); }
async function loadProducts(refresh){
  try {
    const getJ = u => fetch(u).then(r => r.ok ? r.json() : {}).catch(() => ({}));
    const xd = getJ("extra_desc.json"), xu = LANG === "ur" ? getJ("extra_ur.json") : Promise.resolve({}), xi = getJ("extra_img.json");
    const rawP = parseCSV(await getCSVQuick(CONFIG.SHEET_CSV_URL, "products.csv"));
    /* newer descriptions / Urdu names kept in the site files: used only while the sheet still has the old text or no Urdu name */
    const [XD, XU, XI] = await Promise.all([xd, xu, xi]); DVMAP = XI || {};
    const h32 = s => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++){ h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h >>> 0; };
    rawP.forEach(p => { const d = XD[p.code]; if (d && h32((p.description || "").trim()) === d[0]) p.description = d[1]; if (!(p.name_ur || "").trim() && XU[p.code]) p.name_ur = XU[p.code]; });
    PRODUCTS = rawP
      .filter(p => p.name && (p.status || "active").toLowerCase() !== "hidden")
      .map((p, i) => ({
        code: p.code || ("P-" + (i + 1)),
        name: (LANG === "ur" && p.name_ur) ? p.name_ur : p.name,
        cats: list(p.category),
        subs: String(p.subcategory || "").split("|").map(x => x.trim()).filter(Boolean),
        price: num(p.price), old: num(p.old_price),
        sizes: list(p.sizes), colors: list(p.colors),
        images: String(p.images || p.image || "").split("|").map(s => s.trim()).filter(Boolean),
        en: p.name || "",
        desc: (LANG === "ur" && p.description_ur) ? p.description_ur : cleanDesc(p.description || "", p.name || ""),
        tags: list(p.tags).map(t => t.toLowerCase()),
        chart: (p.size_chart || "").trim(),
        sold: (p.status || "").toLowerCase().replace(/\s/g, "") === "soldout",
        deal: (p.deal || "").toLowerCase().trim(), ends: parseEnd(p.deal_ends), stock: (p.stock || "").trim() === "" ? null : num(p.stock),
        group: (p.group || "").trim(), variant: (p.variant || "").trim(),
        order: i
      }));
    PRODUCTS.forEach(p => { if (!p.sizes.length) p.sizes = autoSizes(p); p.facts = autoFacts(p); });
    VARS = {}; PRODUCTS.forEach(p => { if (p.group) (VARS[p.group] = VARS[p.group] || []).push(p); });
    Object.keys(VARS).forEach(g => { if (VARS[g].length < 2) delete VARS[g]; });
  } catch (e) {
    $("#grid").innerHTML = '<div class="empty">Products could not be loaded. Please check your internet and reload the page.</div>';
    return;
  }
  await Promise.all([loadBanners(), loadSubPhotos(), loadCards(), loadCatInfo(), loadReviews()]);
  /* a category's "All" sub-photo becomes its logo everywhere (unless the Categories sheet has its own photo) */
  Object.keys(SUB_PHOTOS).forEach(k => { const [c, sb] = k.split("||"); if (sb === "All" && c !== "*" && !CAT_PHOTO[c]) CAT_PHOTO[c] = SUB_PHOTOS[k]; });
  renderSide();
  renderSlides(); renderQuick(); renderCats(); renderPersonal(); renderSections(); renderVideos(); render();
  if (refresh) return;
  openFromHash();
  const live = CSV_LIVE.splice(0);
  Promise.all(live).then(ch => { if (ch.some(Boolean)){ CSV_REFRESH = true; loadProducts(true).finally(() => { CSV_REFRESH = false; }); } });
}

/* ---------- slider ---------- */
let slideIx = 0, slideTimer, SLIDES = [], slidePaused = false;
const THEMES = {green:"s1", maroon:"s2", blue:"s3", gold:"s4", red:"s5", sale:"s5", image:"sfull", s1:"s1", s2:"s2", s3:"s3", s4:"s4", s5:"s5"};
async function loadBanners(){
  try {
    const ok = r => r.title || r.highlight || ((r.theme || "").toLowerCase() === "image" && r.image);
    let rows = parseCSV(await getCSVQuick(CONFIG.BANNERS_CSV_URL, "banners.csv")).filter(ok);
    if (!rows.length && CONFIG.BANNERS_CSV_URL) rows = parseCSV(await getCSV("", "banners.csv")).filter(ok);
    if (rows.length) SLIDES = rows.map(r => ({theme: THEMES[(r.theme || "").toLowerCase()] || "s1", kick: r.kick, title: esc(r.title) + (r.highlight ? ` <span>${esc(r.highlight)}</span>` : ""),
      text: r.text, btn: r.button || "Shop now", cat: r.category || "all", product: r.product, image: r.image, video: r.video, style: (r.style || "").toLowerCase().trim()}));
  } catch (e) {}
  if (!SLIDES.length) SLIDES = CONFIG.SLIDES.map(s => ({...s, title: s.title}));
}
function renderSlides(){
  const S = SLIDES;
  $("#slider").innerHTML = S.map((s, i) => {
    const p = PRODUCTS.find(x => x.code === s.product);
    const imgs = String(s.image || "").split("|").map(x => x.trim()).filter(Boolean).map(imgUrl);
    const img = imgs[0] || (p ? imgUrl(p.images[0]) : "");
    const H = "h2";
    const go = s.cat && s.cat !== "all" ? `setCat('${jsq(s.cat)}',true)` : `setCat('all',true)`;
    let media = "";
    if (s.video) media = `<div class="pic vid"><video src="${esc(s.video)}" muted loop playsinline autoplay preload="metadata"${img ? ` poster="${esc(img)}"` : ""}></video>${p ? `<span class="tag">${rs(p.price)}</span>` : ""}</div>`;
    else if (img && s.image && !p && s.style === "cutout") media = `<button class="pic cut" onclick="${go}" aria-label="${esc(s.btn)}"><span class="glow"></span><img src="${esc(img)}" alt=""><span class="floor"></span><span class="pchip">✦ ${esc(s.kick ? s.kick.charAt(0) + s.kick.slice(1).toLowerCase() : "New in")}</span></button>`;
    else if (img && s.image && !p) media = `<button class="pic photo" onclick="${go}" aria-label="${esc(s.btn)}"><span class="pin">${imgs.map((u, n) => `<img class="${n ? "" : "on"}" src="${esc(u)}" alt="" ${i || n ? 'loading="lazy"' : 'fetchpriority="high"'}>`).join("")}</span>${imgs.length > 1 ? `<span class="pbar">${imgs.map((u, n) => `<i class="${n ? "" : "on"}"></i>`).join("")}</span>` : ""}<span class="pchip">✦ ${esc(s.kick ? s.kick.charAt(0) + s.kick.slice(1).toLowerCase() : "New in")}</span></button>`;
    else if (img) media = `<button class="pic" onclick="${p ? `openProduct('${jsq(p.code)}')` : go}" aria-label="${esc(p ? p.name : s.btn)}"><img src="${esc(img)}" alt="">${p ? `<span class="tag">${rs(p.price)}</span>` : ""}</button>`;
    else media = `<div class="bigicon">${icon("truck")}</div>`;
    if (s.theme === "sfull" && img) return `<button class="slide sfull ${i === 0 ? "on" : ""}" onclick="${p ? `openProduct('${jsq(p.code)}')` : go}" aria-label="${esc(s.kick || s.btn || "Offer")}"><img src="${esc(img)}" alt="${esc(s.kick || "Offer")}"></button>`;
    return `<div class="slide ${s.theme} ${i === 0 ? "on" : ""}">
      <div style="position:relative;z-index:1">
        <div class="kick">${esc(s.kick || "")}</div><${H}>${s.title}</${H}><p>${esc(s.text || "")}</p>
        <div class="cta"><button class="btn btn-gold" onclick="${go}">${esc(s.btn)} →</button></div>
      </div>${media}</div>`;
  }).join("") + `<div class="dots">${S.map((_, i) => `<button class="${i === 0 ? "on" : ""}" onclick="goSlide(${i},true)" aria-label="Slide ${i + 1}"></button>`).join("")}</div>`;
  startSlides();
  const el = $("#slider"); let x0 = null, y0 = null;
  el.onmouseenter = () => slidePaused = true; el.onmouseleave = () => slidePaused = false;
  el.ontouchstart = e => { x0 = e.touches[0].clientX; y0 = e.touches[0].clientY; slidePaused = true; };
  el.ontouchend = e => {
    if (x0 !== null){ const dx = e.changedTouches[0].clientX - x0, dy = e.changedTouches[0].clientY - y0;
      if (Math.abs(dx) > 40 && Math.abs(dx) > Math.abs(dy)) goSlide(slideIx + (dx < 0 ? 1 : -1), true); }
    x0 = null; setTimeout(() => slidePaused = false, 4000);
  };
}
function startSlides(){ clearInterval(slideTimer); slideTimer = setInterval(() => { if (!slidePaused && !document.hidden) goSlide(slideIx + 1); }, 6000); startPics(); }
/* photos inside the active banner change every 2 seconds */
let picTimer;
function startPics(){
  clearInterval(picTimer);
  const sl = $$(".slide")[slideIx]; if (!sl) return;
  const ims = sl.querySelectorAll(".pic.photo .pin img"), bars = sl.querySelectorAll(".pic.photo .pbar i");
  ims.forEach((im, k) => im.classList.toggle("on", k === 0)); bars.forEach((b, k) => b.classList.toggle("on", k === 0));
  if (ims.length < 2) return;
  let k = 0;
  picTimer = setInterval(() => {
    if (document.hidden) return;
    k = (k + 1) % ims.length;
    ims.forEach((im, n) => im.classList.toggle("on", n === k)); bars.forEach((b, n) => b.classList.toggle("on", n === k));
  }, 2000);
}
function goSlide(i, user){
  const sl = $$(".slide"), d = $$(".dots button"); if (!sl.length) return;
  slideIx = (i + sl.length) % sl.length;
  sl.forEach((s, k) => s.classList.toggle("on", k === slideIx));
  d.forEach((s, k) => s.classList.toggle("on", k === slideIx));
  sl.forEach((s, k) => { const v = s.querySelector("video"); if (v){ if (k === slideIx) v.play().catch(() => {}); else v.pause(); } });
  if (user) startSlides(); else startPics();
}

